def binary_search(L, x):
    low, high = 0, len(L)
    while low < high:
        mid = (low + high) // 2
        if L[mid] < x:
            low = mid + 1
        else:
            high = mid
    if low < len(L) and L[low] == x:
        return low
    return -1

